function formatUssdTxAmount(amt) {
  if (amt < 1 && amt > 0) return amt.toFixed(2);
  if (Number.isInteger(amt)) return amt.toFixed(1);
  const dec = amt.toString().split(".")[1] || "";
  return dec.length === 1 ? amt.toFixed(1) : amt.toFixed(2);
}
