  const [showPhoneSettings, setShowPhoneSettings] = reactExports.useState(false);
  const [selectedTxDetail, setSelectedTxDetail] = reactExports.useState(null);
  const [themeAccent, setThemeAccent] = reactExports.useState("dashen_blue");
